def copy(key: str, language: Language) -> str:
    """One catalogue entry, in the requested language.

    A missing key is a programming error, so it raises rather than returning
    the key itself — a `KeyError` in a test beats a raw `next.submit` rendered
    to a client.
    """
    return _COPY[key][language]
